-- Seed the shared food_catalog.
-- Generated by `python -m bubbly_chef.domain.catalog_seed` from
-- ai-service/bubbly_chef/domain/pantry_catalog.json (issue #548).
-- Additive and idempotent: canonical is the primary key, so re-running or
-- overlapping an existing row is a no-op. icon_slug stays NULL and
-- valid_units keeps its column default. expiry_days and default_location come
-- from the category defaults in domain/expiry.py.
ON CONFLICT (canonical) DO NOTHING;
